      "landing_stat_ai": "Yapay Zeka Onaylı Profiller",
      "landing_stat_blur": "Akıllı Güvenlik Bulanıklığı",
      "landing_stat_cash": "Anında Nakit Para Çekme",
      "landing_why_title": "Neden",
      "landing_why_desc": "Klasik ve sıkıcı sohbet uygulamalarını unutun. Pyngoo en yeni teknolojilerle donatıldı.",
      "landing_feat1_title": "Canlı Görüntülü Sohbet",
      "landing_feat1_desc": "Gerçek insanlarla anında görüntülü eşleş. HD kalitesinde video akışıyla yüz yüze tanışmanın keyfini çıkar.",
      "landing_feat2_title": "Gizemli Sesli Arama",
      "landing_feat2_desc": "Kamerayı açmak istemediğinde tek tuşla sesli moda geç. Sadece sesinle etkile ve yeni arkadaşlar edin.",
      "landing_feat3_title": "Yapay Zeka Doğrulaması",
      "landing_feat3_desc": "Kadın profilleri yapay zeka yüz taramasından geçer. Sahte hesaplara, botlara ve trollere geçit yok!",
      "landing_feat4_title": "Hediye Topla & Kazan",
      "landing_feat4_desc": "Sohbet ederken aldığın dijital hediyeler gerçek elmaslara dönüşür. Dilediğin zaman banka hesabına nakit çek.",
      "landing_feat5_title": "Akıllı Güvenlik Bulanıklığı",
      "landing_feat5_desc": "Görüntülü görüşmeler ilk 4 saniye bulanık başlar. İstenmeyen ve uygunsuz manzaralardan anında korunursunuz.",
      "landing_feat6_title": "%100 Gizlilik & Anonimlik",
      "landing_feat6_desc": "Telefon numarası veya kimlik bilgisi yok. Sadece eğlenceli bir takma ad seç ve dünyaya bağlan.",
      "landing_how_title": "Nasıl",
      "landing_how_works": "Çalışır?",
      "landing_how_desc": "3 basit adımda yeni dünyalara ve insanlara kapı arala.",
      "landing_step1_title": "Modunu Seç",
      "landing_step1_desc": "İster görüntülü ister sesli sohbet butonuna tıkla. Tercih tamamen senin keyfine kalmış.",
      "landing_step2_title": "45 Saniyede Eşleş",
      "landing_step2_desc": "Sistem seni beklemeden, anında en uygun kişiyle bağlasın. 45 saniyelik konuşma başlasın!",
      "landing_step3_title": "Uzat & Arkadaş Ol",
      "landing_step3_desc": "Sohbeti sevdin mi? Süreyi uzat, hediyeler gönder, arkadaş ekle ve sınırsız mesajlaş.",
      "landing_faq_title": "Sıkça Sorulan",
      "landing_faq_highlight": "Sorular",
      "landing_faq_desc": "Aklına takılan tüm soruların cevapları burada.",
      "landing_faq1_q": "Pyngoo nedir ve nasıl çalışır?",
      "landing_faq1_a": "Pyngoo, kimliğinizi ve kişisel bilgilerinizi tamamen gizli tutarak, Türkiye'den ve dünyadan rastgele insanlarla 45 saniyelik sesli veya görüntülü görüşmeler yapabileceğiniz yeni nesil anonim sosyal sohbet platformudur.",
      "landing_faq2_q": "Görüntülü sohbet güvenli mi? Taciz nasıl engelleniyor?",
      "landing_faq2_a": "Pyngoo'da güvenlik en yüksek önceliğimizdir. Görüntülü görüşmeler ilk 4 saniye boyunca özel bir 'Akıllı Bulanıklık' (Safety Blur) filtresiyle başlar. Karşınızdakinin normal bir kullanıcı olduğunu gördüğünüzde ekran netleşir. Ayrıca tek tıkla şikayet ve anında ban sistemiyle kurallara uymayanlar platformdan kalıcı olarak uzaklaştırılır.",
      "landing_faq3_q": "Yapay zeka doğrulaması ne işe yarıyor?",
      "landing_faq3_a": "Platforma kayıt olan kadın kullanıcılar yüz taramasından geçer. Bu sayede sahte profiller, troller ve kadın taklidi yapan dolandırıcı hesaplar tamamen elenir. Erkek kullanıcılar karşılarında %100 gerçek bir insan olduğunu bilir.",
      "landing_faq4_q": "Hediyeleri nasıl nakit paraya dönüştürebilirim?",
      "landing_faq4_a": "Sohbetler ve özel mesajlaşmalar sırasında aldığınız tüm hediyeler (gül, elmas, taç vb.) profilinizde gerçek Elmas bakiyesine dönüşür. Belirli bir limite ulaştığınızda IBAN numaranızı yazarak banka hesabınıza doğrudan nakit para çekebilirsiniz.",
      "landing_faq5_q": "Pyngoo'yu kullanmak ücretli mi?",
      "landing_faq5_a": "Hayır! Uygulamaya kayıt olmak ve günlük ücretsiz eşleşme haklarınızı kullanmak tamamen ücretsizdir. Daha fazla eşleşmek, süre uzatmak veya hediye göndermek isterseniz mağazadan altın paketleri alabilirsiniz.",
      "landing_cta_bottom_title": "Yeni İnsanlarla Tanışmaya Hazır mısın?",
      "landing_cta_bottom_desc": "Hemen şimdi tek bir tıkla anonim dünyadaki yerini al. Hiçbir şey indirmene gerek yok!",
      "landing_cta_bottom_btn": "Sohbete Şimdi Başla 🚀",
