// Akıllı Konum & Türkiye Dil Tespiti
export const detectUserDefaultLanguage = (): string => {
  try {
    // 1. Kullanıcının manuel seçtiği ve saklanan dil tercihi
    const saved = localStorage.getItem('i18nextLng') || localStorage.getItem('pending_language');
    if (saved) {
      const code = saved.slice(0, 2).toLowerCase();
      if (['tr', 'en', 'de', 'fr', 'es', 'ru', 'ar', 'az', 'it', 'pt'].includes(code)) {
        return code;
      }
    }

    // 2. Tarayıcı Dili (navigator.language / languages)
    const navLangs = [navigator.language, ...(navigator.languages || [])].filter(Boolean);
    for (const l of navLangs) {
      const lower = l.toLowerCase();
      if (lower.startsWith('tr')) return 'tr';
      if (lower.startsWith('az')) return 'az';
    }

    // 3. Saat Dilimi (Timezone): Türkiye'de yaşayıp tarayıcısı veya Windows'u İngilizce olan kullanıcılar
    const tz = (Intl.DateTimeFormat().resolvedOptions().timeZone || '').toLowerCase();
    if (tz.includes('istanbul') || tz.includes('turkey')) {
      return 'tr';
    }

    // 4. Diğer diller
    const firstLang = (navigator.language || '').toLowerCase();
    if (firstLang.startsWith('de')) return 'de';
    if (firstLang.startsWith('fr')) return 'fr';
    if (firstLang.startsWith('es')) return 'es';
    if (firstLang.startsWith('ru')) return 'ru';
    if (firstLang.startsWith('ar')) return 'ar';
    if (firstLang.startsWith('it')) return 'it';
    if (firstLang.startsWith('pt')) return 'pt';

    // 5. Varsayılan (Uygulamanın ana merkezi Türkiye olduğu için varsayılan Türkçe!)
    return 'tr';
  } catch (_) {
    return 'tr';
  }
};

const initialDetectedLanguage = detectUserDefaultLanguage();

i18n
  .use(LanguageDetector)
  .use(initReactI18next)
  .init({
    resources,
    lng: localStorage.getItem('i18nextLng') || initialDetectedLanguage,
    fallbackLng: 'tr',
    detection: {
      order: ['localStorage', 'navigator', 'cookie'],
      caches: ['localStorage']
    },
    interpolation: {
      escapeValue: false 
    }
  });

// Dil değiştiğinde sayfa başlığını ve html lang etiketini güncelle
const updateDocumentMeta = (lng: string) => {
  const currentLang = lng ? lng.slice(0, 2).toLowerCase() : 'tr';
  document.documentElement.lang = currentLang;
  const title = i18n.t('page_title');
  if (title) {
    document.title = title;
  }
};

i18n.on('languageChanged', (lng) => {
  updateDocumentMeta(lng);
  try {
    localStorage.setItem('i18nextLng', lng);
    localStorage.setItem('pending_language', lng);
  } catch (_) {}
});

// İlk yüklemede başlığı ayarla
updateDocumentMeta(i18n.language || initialDetectedLanguage);

export default i18n;
